from formula import show

# Factorise x^2 + bx + c: find two whole numbers that multiply to c and add to b
def factor_pair(b, c):
    for p in range(-abs(c), abs(c) + 1):
        if p != 0 and c % p == 0 and p + c // p == b:
            return p, c // p
    return None

for b, c in [(-5, 6), (1, -12), (7, 10), (2, -4)]:
    pair = factor_pair(b, c)
    if pair:
        p, q = pair
        bracket = lambda n: f"(x {'-' if n < 0 else '+'} {abs(n)})"
        print(f"{show(1, b, c)} = {bracket(p)}{bracket(q)}   so x = {-p} or x = {-q}")
    else:
        print(f"{show(1, b, c)}: no whole-number pair, use the formula")

import math

def show(a, b, c):
    """Write ax^2 + bx + c the way you would by hand."""
    s = ("" if a == 1 else str(a)) + "x^2"
    s += f" {'-' if b < 0 else '+'} " + ("" if abs(b) == 1 else str(abs(b))) + "x" if b else ""
    s += f" {'-' if c < 0 else '+'} {abs(c)}" if c else ""
    return s

def solve_quadratic(a, b, c):
    """Real solutions of ax^2 + bx + c = 0."""
    d = b * b - 4 * a * c          # the discriminant
    if d < 0:
        return d, []
    if d == 0:
        return d, [-b / (2 * a)]
    root = math.sqrt(d)
    return d, sorted([(-b - root) / (2 * a), (-b + root) / (2 * a)])

if __name__ == "__main__":
    for a, b, c in [(1, -5, 6), (1, 2, -4), (1, 6, 9), (1, 2, 5)]:
        d, xs = solve_quadratic(a, b, c)
        shown = ", ".join(f"{x:.4g}" for x in xs) or "no real solutions"
        print(f"{show(a, b, c)} = 0".ljust(20), f"discriminant {d:>3}   x = {shown}")

# A ball is thrown up at 20 m/s. Its height after t seconds is roughly h = 20t - 5t^2.
# (Using 5 for half of gravity's 9.8 keeps the numbers simple.)
import math

def times_at_height(h):
    # 20t - 5t^2 = h  becomes  5t^2 - 20t + h = 0
    a, b, c = 5, -20, h
    d = b * b - 4 * a * c
    if d < 0:
        return []
    return sorted({(-b - math.sqrt(d)) / (2 * a), (-b + math.sqrt(d)) / (2 * a)})

for h in (0, 15, 20, 25):
    ts = times_at_height(h)
    print(f"height {h:>2} m: " + (", ".join(f"t = {t:g} s" for t in ts) if ts else "never reached"))
